/**
 * SLATE — the shoemakers.
 *
 * Christian Louboutin, Jimmy Choo, Manolo Blahnik, Dr. Martens, Birkenstock,
 * Clarks, Timberland and UGG. Between them they cover the red carpet, the
 * pavement and the school run, and until now each had a shopfront with one
 * pair of shoes in it.
 *
 * Unlike a high street rail, these houses name their shoes, and the name is
 * the product: So Kate, Hangisi, Romy, 1460, Arizona, Wallabee, the
 * Six Inch Premium, the Classic Ultra Mini. Those names are public record.
 * The heel heights and the leathers are how each house really lists them.
 * Every price, quality figure and wear rate is SLATE's own calibration and
 * says so on the row.
 */

import { REFERENCE_VERSION } from './reference';
import { HOUSE_NOTE } from './labels';
import type { RealGood } from './goods';

const REAL = {
  source: 'calibrated_estimate', confidence: 'high', version: REFERENCE_VERSION,
  note: HOUSE_NOTE,
} as const;

const ALL_YEAR = ['Spring', 'Summer', 'Autumn', 'Winter'];
const WINTER = ['Autumn', 'Winter'];
const SUMMER = ['Spring', 'Summer'];

type Who = 'men' | 'women' | 'unisex';

/** A shoe. The house's own model name, the house's own last. */
const sh = (
  id: string, name: string, brand: string, sub: string, price: number,
  formality: number, quality: number, who: Who = 'unisex', depreciation = 0.32,
  seasons: string[] = ALL_YEAR,
): RealGood => ({
  id, name, type: 'product', category: 'footwear', subcategory: sub, basePrice: price, brand,
  tags: ['wear', 'shoes', sub], quality, depreciation, slot: 'shoes', formality,
  seasons, audience: who, ...REAL,
});

/** Everything else the shoemaker sells: bags, belts, small leather goods, socks. */
const ac = (
  id: string, name: string, brand: string, sub: string, price: number,
  slot: string | undefined, formality: number, quality: number, who: Who = 'unisex', depreciation = 0.30,
): RealGood => ({
  id, name, type: 'product', category: 'accessory', subcategory: sub, basePrice: price, brand,
  tags: ['wear', sub], quality, depreciation, slot, formality, seasons: ALL_YEAR,
  audience: who, ...REAL,
});

/** The clothes the bootmakers really make beside the boots. */
const rw = (
  id: string, name: string, brand: string, sub: string, price: number,
  slot: string, formality: number, quality: number, who: Who = 'unisex',
  depreciation = 0.36, seasons: string[] = ALL_YEAR,
): RealGood => ({
  id, name, type: 'product', category: 'clothing', subcategory: sub, basePrice: price, brand,
  tags: ['wear', sub], quality, depreciation, slot, formality, seasons, audience: who, ...REAL,
});

/** What a sheepskin house sells for the house itself. */
const hm = (
  id: string, name: string, brand: string, sub: string, price: number,
  quality: number, depreciation = 0.34,
): RealGood => ({
  id, name, type: 'product', category: 'home', subcategory: sub, basePrice: price, brand,
  tags: ['home', sub], quality, depreciation, seasons: ALL_YEAR, audience: 'unisex', ...REAL,
});

